(x, y, t) => {
  const w1 = Math.sin(x*0.012+t*0.3)*20+Math.cos(y*0.018-t*0.2)*15;
  const w2 = Math.cos(y*0.014-t*0.25)*18+Math.sin(x*0.016+t*0.35)*12;
  const w3 = Math.sin((x+y)*0.008+t*0.15)*25+Math.cos((x-y)*0.01-t*0.18)*20;
  const sx=x+w1+w3*0.5, sy=y+w2+w3*0.5;
  const wx2=Math.sin(sx*0.025+sy*0.015+t*0.5)*8, wy2=Math.cos(sx*0.018-sy*0.022+t*0.45)*8;
  const fx=sx+wx2, fy=sy+wy2;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,5.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.3],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,0.8],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.13,1.4,4.2],
    [200+Math.sin(t*0.38+6)*110,220+Math.cos(t*0.48+3)*70,0.085,2.4,2.0],
    [300+Math.cos(t*0.42+2)*80,30+Math.sin(t*0.58+5)*60,0.095,1.8,5.5]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.4+ph*0.5)*0.5;
  }
  const act=aS/10,inh=iS/10,har=hS/10;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg3=Math.sin(fx*0.08+fy*0.06-t*1.8)*0.15+Math.cos(fx*0.05-fy*0.09+t*1.4)*0.15;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120,dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
