  const sp2=Math.sin(dist*0.08-ang*5-t*2.0)*0.15+Math.cos(dist*0.06+ang*2-t*0.8)*0.15;
  const spiral=sp1+sp2;
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.sin(fx*0.22)*Math.sin(fy*0.22)*Math.cos(fx*0.18+fy*0.18-t*0.7)*0.15;
  const fine=Math.sin(fx*0.3+t*3)*Math.sin(fy*0.35-t*2.5)*0.1;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+har*0.2)*2.2);
  const feedback=Math.tanh(reaction*1.5+cell+cell2+fine)*0.8;
  const blend=reaction*0.6+feedback*0.3+cell*0.1,v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,40,80],[15,75,105],[20,130,130],[45,170,145],
    [180,190,80],[220,175,55],[215,130,60],[185,75,65],
    [140,45,70],[80,25,65],[30,15,55],[5,10,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const shimmer=1.0+Math.sin(har*3.14)*0.05,total=lum*edge*shimmer;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*total)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*total)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*total)|0
  ];
}
